/**
 * Loads the post list and individual post bodies from static files.
 * The list comes from posts-index.json (generated by `npm run build`);
 * each body is the raw markdown file under posts/.
 */

export async function fetchPostsList() {
  const response = await fetch('posts-index.json');

  if (response.status === 404) {
    throw new Error(
      'posts-index.json is missing. Run "npm run build" and refresh the page.'
    );
  }

  if (!response.ok) {
    throw new Error('The list of posts could not be loaded.');
  }

  return response.json();
}

export async function fetchPostBySlug(slug) {
  const validSlugPattern = /^[A-Za-z0-9][A-Za-z0-9_-]*$/;

  if (!validSlugPattern.test(slug)) {
    return null;
  }

  const response = await fetch(`posts/${encodeURIComponent(slug)}.md`);

  if (response.status === 404) {
    return null;
  }

  if (!response.ok) {
    throw new Error('This post could not be loaded.');
  }

  const markdown = await response.text();
  return { slug, markdown };
}
